import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../common';
import './PaymentsPage.css';

export default function PaymentsPage({payroll,money}) { const paid=payroll.filter(p=>p.status==='Paid').reduce((s,p)=>s+Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0),0); return <div className="module-page module-page--payments"><PageTitle eyebrow="FINANCE" title="Payments" subtitle="A high-level view of recorded payroll payouts in this prototype."/><div className="stats-grid"><Stat label="Recorded payouts" value={money(paid)} change="Payroll marked Paid" icon="₹" tone="green" foot="Demo records only"/><Stat label="Payroll entries" value={payroll.length} change="All generated entries" icon="▤" tone="purple" foot="Open Payroll to manage"/><Stat label="Pending drafts" value={payroll.filter(p=>p.status==='Draft').length} change="Not paid" icon="◷" tone="orange" foot="Requires owner review"/><Stat label="Customer collections" value="Not connected" change="No payment gateway" icon="↗" tone="blue" foot="Real collections not recorded"/></div><div className="notice">This is not a payment gateway or accounting ledger. Do not treat demo values as actual transactions or tax records.</div></div>; }
